            let ptr = boxed.as_mut_ptr();
            std::ptr::write_bytes(ptr, 0, 1);
            let params = &mut *ptr;
            params.p0 = 2002.0;
            params.p1 = 3.0;
            params.p2 = 0.0;
            params.p3 = 0.0;
            params.p4 = 0.001;
            validate_parameter("minr", params.p4, Some((0.0, "0.0")), false, None, true, &[]).expect("generated Verilog-A parameter default must satisfy declared range");
